insert into public.software (name, slug, tagline, description_short, description_full, logo_url, category_id, starting_price, price_currency, billing_period, price_is_net, price_unit, free_trial, trial_days, free_version, free_demo, pricing_plans, pricing_note, features, top_features, integrations, pros, cons, ideal_for, brand_color, gobd_compliant, datev_interface, e_invoicing, elster_submission, hosting_location, dpa_available, iso27001, tse_certified, skr_support, german_support, vendor_country, compliance_checked_at, affiliate_url, vendor_website, affiliate_network, vendor_name, founded_year, vendor_hq, support_types, countries_available, languages, editorial_rating, editorial_ease, editorial_value, editorial_service, editorial_functionality, editorial_verdict, editorial_review, editorial_author, editorial_tested_at, status, featured) values
('Asana', 'asana', 'Arbeitsmanagement für Teams', 'Verbreitetes Arbeitsmanagement-Tool mit Listen, Boards, Zeitleisten und Portfolios.', '<p>Asana hilft Teams, Aufgaben, Projekte und Ziele zu organisieren. Listen, Boards, Zeitleisten und Portfolios geben unterschiedlichen Rollen die passende Sicht auf die Arbeit.</p><p>Standardmäßig werden Daten in den USA gespeichert; EU-Datenresidenz ist in höheren Tarifen verfügbar.</p>', null, (select id from public.categories where slug = 'projektmanagement'), 0, 'EUR', 'month', true, 'user', true, null, true, false, '[{"name":"Personal","price":0,"period":"month","unit":"user","features":["Bis zu 2 Nutzer"]},{"name":"Starter","price":13.49,"period":"month","unit":"user","features":["jährlich 10,99 €"],"highlighted":true},{"name":"Advanced","price":30.49,"period":"month","unit":"user","features":["jährlich 24,99 €"]}]'::jsonb, null, '["Aufgaben & Kanban","Gantt-Diagramm","Ressourcen & Auslastung","Dokumente & Dateien","Gastzugänge","Vorlagen"]'::jsonb, '["Portfolios und Ziele","Zeitleiste","Kostenlose Version"]'::jsonb, '["Slack","Microsoft Teams","Google Workspace","Zoom","Salesforce"]'::jsonb, '["Sehr ausgereift","Große Verbreitung"]'::jsonb, '["Standard-Hosting außerhalb der EU","Keine integrierte Zeiterfassung"]'::jsonb, 'Teams mit internationalem Umfeld.', null, null, null, '[]'::jsonb, null, 'Drittland', true, true, null, '[]'::jsonb, false, 'USA', '2026-09-22', null, 'https://asana.com/de', 'keins', 'Asana, Inc.', 2008, 'San Francisco (USA)', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch","und weitere"]'::jsonb, 4.3, 4.4, 3.9, 4, 4.5, 'Asana ist eines der ausgereiftesten Werkzeuge für Aufgaben und Projekte in wachsenden Teams. Für kleine Teams reicht oft die kostenlose Version, im Advanced-Tarif wird es teuer.', '<h3>Stärken</h3><p>Asana verbindet Listen, Boards, Zeitleisten und Kalender mit Zielen und Portfolios. Abhängigkeiten zwischen Aufgaben, Regeln für Automatisierungen und saubere Berichte machen es zu einem starken Werkzeug für Teams mit vielen parallelen Projekten.</p><h3>Preise</h3><p>Personal ist kostenlos für bis zu zwei Nutzer. Starter kostet 13,49 € je Nutzer im Monat, jährlich 10,99 €. Advanced liegt bei 30,49 €, jährlich 24,99 €. Enterprise gibt es auf Anfrage.</p><h3>Fazit</h3><p>Asana lohnt sich für Teams ab etwa zehn Personen mit vielen Projekten und Abhängigkeiten. Für einfache Aufgabenlisten genügt MeisterTask.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('clockodo', 'clockodo', 'Zeiterfassung für Arbeitszeit und Projekte', 'Online-Zeiterfassung aus Hamburg für Arbeits- und Projektzeiten, konform zum BAG-Beschluss, Hosting in Deutschland.', '<p>clockodo erfasst Arbeitszeiten und Projektzeiten per App, Browser oder Terminal. Pausen, Überstunden und Abwesenheiten werden automatisch verrechnet; Verstöße gegen das Arbeitszeitgesetz werden angezeigt.</p><p>Die Software unterstützt Unternehmen dabei, die Pflicht zur Arbeitszeiterfassung nach dem BAG-Beschluss von 2022 umzusetzen.</p>', null, (select id from public.categories where slug = 'zeiterfassung'), 4, 'EUR', 'month', true, 'user', true, 14, false, false, '[{"name":"Solo","price":0,"period":"month","unit":"user","features":["Kostenlos für eine Person"]},{"name":"Basic","price":4,"period":"month","unit":"user","features":[]},{"name":"Pro","price":10,"period":"month","unit":"user","features":[],"highlighted":true},{"name":"Pro Plus","price":12,"period":"month","unit":"user","features":[]}]'::jsonb, null, '["Mobile Zeiterfassung","Projektzeiten","Pausen- & ArbZG-Prüfung","Urlaubsverwaltung","Terminal & NFC","Lohnexport","Überstundenkonto","Manipulationsschutz"]'::jsonb, '["Arbeits- und Projektzeit in einem","ArbZG-Prüfung","Serverstandort Deutschland"]'::jsonb, '["DATEV","Personio","Lexware Office","sevdesk","awork"]'::jsonb, '["Einfache Bedienung","Gute Projektauswertungen"]'::jsonb, '["Keine Schichtplanung","Auswertungen teils starr"]'::jsonb, 'Dienstleister und Agenturen.', null, null, null, '[]'::jsonb, null, 'Deutschland', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.clockodo.com/de/', 'keins', 'clockodo GmbH', null, 'Hamburg', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.4, 4.5, 4.4, 4.2, 4.2, 'clockodo aus Hamburg ist eine unkomplizierte Online-Zeiterfassung für Arbeits- und Projektzeiten, gehostet in Deutschland. Mit Preisen ab 4 € je Nutzer gehört sie zu den fairsten Angeboten.', '<h3>Was clockodo leistet</h3><p>clockodo erfasst Arbeitszeiten, Pausen und Projektzeiten per Browser, App oder Terminal und erfüllt damit die Anforderungen an die Arbeitszeiterfassung nach dem Beschluss des Bundesarbeitsgerichts. Projektzeiten lassen sich nach Kunde und Leistung auswerten und für die Abrechnung nutzen.</p><h3>Preise</h3><p>Für eine einzelne Person ist clockodo kostenlos. Basic kostet 4 €, Pro 10 € und Pro Plus 12 € je Nutzer im Monat, im ersten Jahr gibt es auf Pro und Pro Plus einen Rabatt. Alle Preise sind netto, die Testphase dauert 14 Tage.</p><h3>Fazit</h3><p>Für Agenturen, Beratungen und Handwerksbetriebe, die Arbeits- und Projektzeiten sauber trennen wollen, ist clockodo eine sehr gute Wahl.</p>', 'Nadeem Abbas', '2026-09-22', 'published', true),
('Papershift', 'papershift', 'Dienstplanung und Zeiterfassung', 'Dienstplanung, Zeiterfassung und Urlaubsverwaltung aus Karlsruhe, besonders für Gastronomie, Handel und Pflege.', '<p>Papershift kombiniert Schichtplanung mit Zeiterfassung und Abwesenheitsmanagement. Mitarbeitende stempeln per App oder Tablet-Terminal, Dienstpläne werden per Drag-and-drop erstellt.</p><p>Stunden und Zuschläge lassen sich an die Lohnabrechnung exportieren.</p>', null, (select id from public.categories where slug = 'zeiterfassung'), 64, 'EUR', 'month', true, 'user', true, 14, false, false, '[]'::jsonb, 'für 16 Mitarbeitende, zzgl. 39 € Grundgebühr', '["Mobile Zeiterfassung","Pausen- & ArbZG-Prüfung","Urlaubsverwaltung","Schichtplanung","Terminal & NFC","Lohnexport","Überstundenkonto","Manipulationsschutz"]'::jsonb, '["Schichtplanung per Drag-and-drop","Tablet-Stempeluhr","Lohnexport"]'::jsonb, '["DATEV","Personio","Lexware lohn+gehalt"]'::jsonb, '["Stark bei Schichtbetrieben","Einfache Stempeluhr"]'::jsonb, '["Projektzeiten weniger ausgeprägt","Viele Add-ons"]'::jsonb, 'Gastronomie, Einzelhandel und Pflege.', null, null, null, '[]'::jsonb, null, 'Deutschland', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.papershift.com', 'keins', 'Papershift GmbH', null, 'Karlsruhe', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.1, 4.2, 3.8, 4.1, 4.3, 'Papershift aus Karlsruhe verbindet Dienstplanung, Zeiterfassung und Urlaubsverwaltung. Für Gastronomie, Handel und Pflege mit wechselnden Schichten ist es eine durchdachte Lösung.', '<h3>Worauf Papershift spezialisiert ist</h3><p>Schichtbetriebe haben andere Sorgen als Büroteams. Papershift plant Dienste, berücksichtigt Verfügbarkeiten und Qualifikationen, erfasst die tatsächlich geleisteten Stunden und bereitet sie für die Lohnabrechnung vor.</p><h3>Preise</h3><p>Die Pakete Core, Premium und Professional werden für eine Gruppe von 16 Mitarbeitenden angeboten und kosten 64 €, 96 € und 144 € im Monat, bei jährlicher Zahlung zehn Prozent weniger. Hinzu kommt eine Grundgebühr von 39 € im Monat. Die Testphase dauert 14 Tage.</p><h3>Fazit</h3><p>Für Betriebe mit Schichtplanung ist Papershift eine der rundesten Lösungen. Reine Bürobetriebe sind mit clockodo oder Crewmeister günstiger bedient.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('ZEP', 'zep', 'Projektzeiterfassung für Dienstleister', 'Projektzeiterfassung und Projektcontrolling für Beratungs- und IT-Dienstleister.', '<p>ZEP ist auf Projektzeiterfassung für Dienstleister spezialisiert: Zeiten, Reisekosten und Belege werden projektgenau erfasst und für die Abrechnung aufbereitet.</p><p>Die Lösung wird in Deutschland gehostet.</p>', null, (select id from public.categories where slug = 'zeiterfassung'), 2, 'EUR', 'month', true, 'user', true, 14, false, false, '[{"name":"ZEP Clock","price":2,"period":"month","unit":"user","features":["Digitale Stempeluhr"]},{"name":"ZEP Compact","price":7,"period":"month","unit":"user","features":["Projekt- und Kundenzeiten"],"highlighted":true},{"name":"ZEP Professional","price":18,"period":"month","unit":"user","features":["Controlling und Reisekosten"]}]'::jsonb, null, '["Mobile Zeiterfassung","Projektzeiten","Pausen- & ArbZG-Prüfung","Urlaubsverwaltung","Lohnexport","Überstundenkonto","Manipulationsschutz"]'::jsonb, '["Projektcontrolling","Reisekosten","Abrechnungsvorbereitung"]'::jsonb, '["DATEV","Jira","Outlook"]'::jsonb, '["Sehr gute Projektauswertungen","Für Berater optimiert"]'::jsonb, '["Oberfläche wenig modern","Keine Schichtplanung"]'::jsonb, 'IT- und Beratungsunternehmen.', null, null, null, '[]'::jsonb, null, 'Deutschland', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.zep.de', 'keins', 'provantis IT Solutions GmbH', null, 'Ditzingen', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.2, 4, 4.3, 4.2, 4.4, 'ZEP ist die Wahl für Beratungen und IT-Dienstleister, die Projektzeiten nicht nur erfassen, sondern auch steuern und abrechnen wollen. Die Tarife reichen von der einfachen Stempeluhr bis zur Professional-Services-Lösung.', '<h3>Die Tarife</h3><p>ZEP Clock ist eine digitale Stempeluhr ab 2 € je Nutzer im Monat. ZEP Compact für 7 € ergänzt projekt- und kundenbezogene Zeiten mit Auswertungen. ZEP Professional für 18 € ist eine Lösung für Professional Services mit Controlling und Reisekosten. Alle Tarife lassen sich 14 Tage kostenlos testen.</p><h3>Stärken</h3><p>Projektbudgets, Stundensätze und Abrechnung sind eng verzahnt. Für Beratungshäuser, die Stunden gegenüber Kunden belegen müssen, ist das der entscheidende Vorteil. Für Non-Profits und Startups gibt es Rabatte, studentische Unternehmensberatungen nutzen ZEP kostenlos.</p><h3>Fazit</h3><p>Wer Projektzeiten in Umsatz verwandelt, sollte ZEP Compact oder Professional ernsthaft prüfen.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('TimeTac', 'timetac', 'Zeiterfassung und Urlaubsverwaltung aus Österreich', 'Cloud-Zeiterfassung mit Projektzeiten, Urlaubsverwaltung und Terminals für DACH-Unternehmen.', '<p>TimeTac bietet Arbeitszeit- und Projektzeiterfassung, Urlaubsverwaltung und Terminal-Lösungen für Unternehmen im DACH-Raum. Die Software berücksichtigt die arbeitsrechtlichen Vorgaben in Deutschland und Österreich.</p><p>Die Daten werden in der EU gehostet.</p>', null, (select id from public.categories where slug = 'zeiterfassung'), null, 'EUR', 'month', true, 'user', true, 30, false, true, '[]'::jsonb, null, '["Mobile Zeiterfassung","Projektzeiten","Pausen- & ArbZG-Prüfung","Urlaubsverwaltung","Terminal & NFC","Lohnexport","Überstundenkonto","Manipulationsschutz"]'::jsonb, '["DACH-Arbeitsrecht","Terminals und NFC","Urlaubsverwaltung"]'::jsonb, '["DATEV","BMD","Outlook"]'::jsonb, '["Für DACH gebaut","Viele Erfassungswege"]'::jsonb, '["Einrichtung etwas aufwendig","Preis nur auf Anfrage"]'::jsonb, 'Unternehmen mit Standorten in Deutschland und Österreich.', null, null, null, '[]'::jsonb, null, 'EU', true, null, null, '[]'::jsonb, true, 'Österreich', '2026-09-22', null, 'https://www.timetac.com/de/', 'keins', 'TimeTac GmbH', null, 'Graz (Österreich)', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.1, 4.1, 3.9, 4.2, 4.3, 'TimeTac ist eine ausgereifte Zeiterfassung mit Projektzeiten, Urlaubsverwaltung und Terminals. Die Testphase von 30 Tagen ist großzügig, Preise gibt es auf der Anbieterseite im Detail.', '<h3>Funktionen</h3><p>TimeTac erfasst Arbeitszeiten per App, Browser oder Terminal, verwaltet Abwesenheiten und bietet Projektzeiterfassung. Die Software richtet sich an kleine bis große Unternehmen und bietet Schnittstellen zur Lohnabrechnung.</p><h3>Test und Kosten</h3><p>Die Testphase dauert 30 Tage und kommt ohne Kreditkarte aus. Die Preise richten sich nach Modulen und Nutzerzahl, eine persönliche Beratung ist kostenlos.</p><h3>Fazit</h3><p>Für Unternehmen, die mehr als eine einfache Stempeluhr brauchen und mehrere Standorte verwalten, ist TimeTac eine solide Wahl.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Crewmeister', 'crewmeister', 'Einfache Zeiterfassung für kleine Betriebe', 'Einfache Zeiterfassung und Abwesenheitsverwaltung für Handwerk, Handel und kleine Betriebe.', '<p>Crewmeister richtet sich an kleine Betriebe, die die Arbeitszeiterfassung ohne großen Aufwand umsetzen wollen. Mitarbeitende stempeln per App, Chefs sehen Anwesenheiten und Überstunden auf einen Blick.</p><p>Die Daten werden in Deutschland gespeichert.</p>', null, (select id from public.categories where slug = 'zeiterfassung'), 1.5, 'EUR', 'month', true, 'user', true, 14, false, false, '[{"name":"Go","price":1.5,"period":"month","unit":"user","features":["Zeiterfassung per App und Terminal"]},{"name":"Easy","price":2,"period":"month","unit":"user","features":["Urlaubsplaner und Abwesenheiten"],"highlighted":true},{"name":"Pro","price":3,"period":"month","unit":"user","features":["Zuschläge, erweiterte Projektzeiten"]}]'::jsonb, 'bei jährlicher Zahlung', '["Mobile Zeiterfassung","Projektzeiten","Pausen- & ArbZG-Prüfung","Urlaubsverwaltung","Schichtplanung","Lohnexport","Überstundenkonto"]'::jsonb, '["Sehr einfach","Für kleine Betriebe","Hosting in Deutschland"]'::jsonb, '["DATEV","Lexware lohn+gehalt"]'::jsonb, '["In Minuten startklar","Günstig für kleine Teams"]'::jsonb, '["Wenig Tiefe für große Unternehmen","Auswertungen einfach"]'::jsonb, 'Handwerk und kleine Betriebe bis 50 Mitarbeitende.', null, null, null, '[]'::jsonb, null, 'Deutschland', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://crewmeister.com/de/', 'keins', 'Crewmeister GmbH', null, 'Berlin', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.3, 4.6, 4.7, 4, 3.9, 'Crewmeister ist die günstigste ernstzunehmende Zeiterfassung in diesem Vergleich. Ab 1,50 € je Nutzer bekommen kleine Betriebe eine einfache App mit Terminal und Urlaubsplaner.', '<h3>Tarife</h3><p>Go kostet 1,50 € je Nutzer im Monat bei jährlicher Zahlung und umfasst Zeiterfassung per App und Terminal, Projektzeiten und GPS. Easy für 2 € ergänzt Urlaubsplaner, Abwesenheiten und Überstundenkonto. Pro für 3 € bringt Zuschläge, erweiterte Projektzeiten und individuelle Berechtigungen. Schichtplaner und DATEV-Anbindung lassen sich hinzubuchen.</p><h3>Test</h3><p>Die Testphase dauert 14 Tage, verlangt keine Zahlungsdaten und endet automatisch. Bei jährlicher Zahlung ist ein Monat gratis.</p><h3>Fazit</h3><p>Für Kleinbetriebe, die die Arbeitszeiterfassung schnell und günstig umsetzen wollen, ist Crewmeister kaum zu schlagen. Für komplexe Projektcontrollings ist ZEP die bessere Wahl.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('DocuWare', 'docuware', 'Dokumentenmanagement und Workflow-Automatisierung', 'DMS mit revisionssicherer Archivierung und Workflows für Rechnungseingang, Personal und Verträge.', '<p>DocuWare ist ein etabliertes Dokumentenmanagement-System aus Germering bei München. Dokumente werden revisionssicher archiviert, per OCR indexiert und in Workflows weiterverarbeitet, etwa im Rechnungseingang.</p><p>Die Cloud-Variante wird in Rechenzentren in der EU betrieben; alternativ ist ein Betrieb im eigenen Haus möglich.</p>', null, (select id from public.categories where slug = 'dokumentenmanagement'), null, 'EUR', 'month', true, 'user', true, null, false, true, '[]'::jsonb, null, '["Revisionssichere Archivierung","Volltextsuche & OCR","Rechnungseingangsworkflow","E-Rechnung (XRechnung/ZUGFeRD)","Versionierung","Rollen & Rechte","DATEV-Anbindung","E-Mail-Archivierung","Mobile App"]'::jsonb, '["Workflow-Automatisierung","Rechnungseingang","Cloud oder on-premise"]'::jsonb, '["DATEV","SAP","Microsoft Dynamics","Outlook","Salesforce"]'::jsonb, '["Sehr ausgereift","Starke Workflows"]'::jsonb, '["Einführung über Partner","Preis nur auf Anfrage"]'::jsonb, 'Mittelständler mit hohem Dokumentenaufkommen.', null, 'ja', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, null, 'EU', true, true, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://start.docuware.com/de/', 'keins', 'DocuWare GmbH', 1988, 'Germering', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch","und weitere"]'::jsonb, 4.3, 4, 3.8, 4.3, 4.7, 'DocuWare aus Germering bei München ist eines der etabliertesten Dokumentenmanagement-Systeme im deutschen Mittelstand. Stark bei revisionssicherer Archivierung und Workflows wie dem Rechnungseingang.', '<h3>Was DocuWare leistet</h3><p>Dokumente werden revisionssicher archiviert, per Texterkennung indexiert und in Workflows weiterverarbeitet, etwa im Rechnungseingang mit Freigabe und Übergabe an die Buchhaltung. Die Lösung gibt es als Cloud und für den Betrieb im eigenen Haus.</p><h3>Kosten</h3><p>Preise gibt es auf Anfrage über Partner, abhängig von Nutzern, Speicher und Workflows. Eine Demo ist kostenlos.</p><h3>Fazit</h3><p>Für Mittelständler, die Papierarchive ablösen und Freigabeprozesse digitalisieren wollen, gehört DocuWare auf die Auswahlliste.</p>', 'Nadeem Abbas', '2026-09-22', 'published', true),
('d.velop documents', 'd-velop-documents', 'Dokumentenmanagement aus dem Münsterland', 'Cloud-DMS mit revisionssicherer Archivierung, Workflows und DATEV-Integration, Hosting in Deutschland.', '<p>d.velop documents ist das Cloud-DMS der d.velop AG aus Gescher. Dokumente werden revisionssicher archiviert und in Prozessen wie Rechnungseingang oder Vertragsmanagement verarbeitet.</p><p>Die Daten liegen in deutschen Rechenzentren; eine enge Integration mit DATEV unterstützt die Zusammenarbeit mit der Steuerkanzlei.</p>', null, (select id from public.categories where slug = 'dokumentenmanagement'), null, 'EUR', 'month', true, 'user', true, null, false, true, '[]'::jsonb, null, '["Revisionssichere Archivierung","Volltextsuche & OCR","Rechnungseingangsworkflow","E-Rechnung (XRechnung/ZUGFeRD)","Versionierung","Rollen & Rechte","DATEV-Anbindung","E-Mail-Archivierung","Mobile App","Verfahrensdokumentation"]'::jsonb, '["Hosting in Deutschland","DATEV-Integration","Vertragsmanagement"]'::jsonb, '["DATEV","Microsoft 365","SAP","Outlook"]'::jsonb, '["Deutscher Anbieter mit deutschem Hosting","Gute DATEV-Anbindung"]'::jsonb, '["Viele Module","Preis nur auf Anfrage"]'::jsonb, 'Mittelständler, die Dokumente vollständig in die Cloud verlagern.', null, 'ja', 'vollintegriert', '["XRechnung","ZUGFeRD"]'::jsonb, null, 'Deutschland', true, true, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.d-velop.de', 'keins', 'd.velop AG', null, 'Gescher', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.2, 4, 3.9, 4.2, 4.6, 'd.velop documents aus Gescher ist ein Cloud-Dokumentenmanagement mit revisionssicherer Archivierung, Workflows und DATEV-Integration, gehostet in Deutschland.', '<h3>Einordnung</h3><p>d.velop gehört zu den großen deutschen DMS-Anbietern. Die Cloud-Lösung verbindet Archiv, Akten und Workflows und bietet eine enge Integration in DATEV und Microsoft 365. Viele Kommunen und Mittelständler arbeiten damit.</p><h3>Kosten</h3><p>Preise gibt es auf Anfrage, eine Demo ist kostenlos. Ein großes Partnernetz übernimmt die Einführung.</p><h3>Fazit</h3><p>Für Unternehmen mit DATEV-Kanzlei und Microsoft-Umgebung ist d.velop documents eine starke Wahl.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false)
